#include "../Source/PluginProcessor.h"
#include <cstdio>
#include <cstdlib>
using namespace wavemover;
static int tests=0;
static void check(bool v,const char*m){++tests;if(!v){std::fprintf(stderr,"HOST FAIL: %s\n",m);std::exit(1);}}
int main(int argc,char**argv){
 juce::ScopedJuceInitialiser_GUI gui;
 const auto directory=argc>2?juce::File(argv[2]):juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("WaveMover-tests");directory.createDirectory();
 WaveMoverProcessor p;check(std::isinf(p.getTailLengthSeconds()),"editor reports an ongoing audition source to the host");
 for(int channels:{1,2})for(double rate:{44100.,48000.,96000.}){
  juce::AudioProcessor::BusesLayout layout;layout.inputBuses.add(channels==1?juce::AudioChannelSet::mono():juce::AudioChannelSet::stereo());layout.outputBuses.add(layout.inputBuses[0]);check(p.setBusesLayout(layout),"mono/stereo layout");p.prepareToPlay(rate,32);
  p.startCapture();std::size_t total=0;
  for(int blockSize:{1,16,32,64,511,2048}){juce::AudioBuffer<float>buffer(channels,blockSize);for(int c=0;c<channels;++c)for(int i=0;i<blockSize;++i)buffer.setSample(c,i,static_cast<float>(.4*std::sin((static_cast<double>(total+i)+c)*.02)));juce::AudioBuffer<float>before;before.makeCopyOf(buffer);juce::MidiBuffer midi;p.processBlock(buffer,midi);for(int c=0;c<channels;++c)for(int i=0;i<blockSize;++i)check(buffer.getSample(c,i)==before.getSample(c,i),"capture must pass input unchanged");total+=static_cast<std::size_t>(blockSize);}
  check(p.finishCapture(),"nonempty capture");auto captured=p.snapshot();check(captured.audio&&captured.audio->frames()==total,"capture has no dropped/duplicated samples");for(int c=0;c<channels;++c)for(std::size_t i=0;i<total;++i)check(std::abs(captured.audio->data[c][i]-static_cast<float>(.4*std::sin((static_cast<double>(i)+c)*.02)))<1e-6f,"captured sample order");
  const auto path=directory.getChildFile("roundtrip_"+juce::String(channels)+"_"+juce::String(rate,0)+".wav");WaveMoverProcessor::writeAudio(path,*captured.audio);auto round=WaveMoverProcessor::readAudio(path);check(round.frames()==total&&round.rate==rate&&round.channels()==channels,"WAV metadata roundtrip");check(round.data==captured.audio->data,"float WAV preserves samples exactly");
  p.setSelection({0,total});p.play();juce::AudioBuffer<float>preview(channels,static_cast<int>(total+10));preview.clear();juce::MidiBuffer midi;p.processBlock(preview,midi);for(int c=0;c<channels;++c)for(std::size_t i=0;i<total;++i)check(preview.getSample(c,static_cast<int>(i))==captured.audio->data[c][i],"audition plays imported audio");check(!p.playing(),"preview stops at exact end");p.releaseResources();
 }
 Clip source(2,48000,48000);for(int c=0;c<2;++c)for(std::size_t i=0;i<source.frames();++i)source.data[c][i]=static_cast<float>(.2*std::sin(2*pi*220*static_cast<double>(i)/48000.))*(c?-.5f:1.f);
 p.load(source,"Teste externo.wav");p.setMarkers({12000,24000,36000},"Split");auto result=render(source,Op::Reverse,{});p.commit(std::move(result.audio),{12000,24000,36000},{5000,40000},"Reverse");check(p.snapshot().audio->data!=source.data,"edit applied");p.undo();check(p.snapshot().audio->data==source.data,"undo restored source");p.redo();check(p.snapshot().audio->data!=source.data,"redo restored edit");
 juce::MemoryBlock state;p.getStateInformation(state);WaveMoverProcessor restored;restored.setStateInformation(state.getData(),static_cast<int>(state.getSize()));check(restored.snapshot().audio->data==p.snapshot().audio->data,"state embeds edited audio");check(restored.snapshot().original->data==source.data,"state embeds original independent of external file");check(restored.snapshot().markers==p.snapshot().markers,"state restores splits");check(restored.snapshot().selection.begin==5000&&restored.snapshot().selection.end==40000,"state restores selection");
 {std::unique_ptr<juce::AudioProcessorEditor>editor(restored.createEditor());check(editor!=nullptr,"native editor constructed");auto image=editor->createComponentSnapshot(editor->getLocalBounds());auto stream=directory.getChildFile("WaveMover_UI.png").createOutputStream();juce::PNGImageFormat png;check(stream&&png.writeImageToStream(image,*stream),"native editor screenshot");}
 if(argc>1){juce::AudioPluginFormatManager formats;formats.addFormat(new juce::VST3PluginFormat);juce::OwnedArray<juce::PluginDescription>descriptions;formats.getFormat(0)->findAllTypesForFile(descriptions,juce::String(argv[1]));check(descriptions.size()==1,"compiled VST3 is discoverable");juce::String error;auto instance=formats.createPluginInstance(*descriptions[0],48000,512,error);if(!instance)std::fprintf(stderr,"VST3 load: %s\n",error.toRawUTF8());check(instance!=nullptr,"compiled VST3 instantiated by native host");instance->prepareToPlay(48000,512);juce::AudioBuffer<float>buffer(2,512);for(int c=0;c<2;++c)for(int i=0;i<512;++i)buffer.setSample(c,i,.25f);juce::MidiBuffer midi;instance->processBlock(buffer,midi);check(buffer.getSample(0,511)==.25f&&buffer.getSample(1,0)==.25f,"compiled VST3 default dry passthrough");juce::XmlElement container("VST3PluginState");container.createNewChildElement("IComponent")->addTextElement(state.toBase64Encoding());juce::MemoryBlock hostState;juce::AudioProcessor::copyXmlToBinary(container,hostState);instance->setStateInformation(hostState.getData(),static_cast<int>(hostState.getSize()));juce::MemoryBlock nativeState;instance->getStateInformation(nativeState);auto nativeXml=juce::AudioProcessor::getXmlFromBinary(nativeState.getData(),static_cast<int>(nativeState.getSize()));check(nativeXml!=nullptr,"compiled VST3 returns host state envelope");auto* component=nativeXml->getChildByName("IComponent");check(component!=nullptr,"compiled VST3 state contains component");juce::MemoryBlock componentBytes;check(componentBytes.fromBase64Encoding(component->getAllSubText()),"compiled component state decodes");WaveMoverProcessor fromNative;fromNative.setStateInformation(componentBytes.getData(),static_cast<int>(componentBytes.getSize()));check(fromNative.snapshot().audio&&fromNative.snapshot().audio->data==p.snapshot().audio->data,"compiled VST3 persists edited audio");check(fromNative.snapshot().original&&fromNative.snapshot().original->data==source.data,"compiled VST3 persists original audio");instance->releaseResources();}
 std::printf("WaveMover native host: %d checks passed\n",tests);
}
